codeExamples.code:
-- SQL Server: actual plan with row counts
SET STATISTICS XML ON;
SELECT o.order_id, o.order_date
FROM   orders AS o
WHERE  o.customer_id = 42;
SET STATISTICS XML OFF;

-- PostgreSQL: actual plan with timing
EXPLAIN (ANALYZE, BUFFERS)
SELECT o.order_id, o.order_date
FROM   orders AS o
WHERE  o.customer_id = 42;

-- Selective predicate (few rows) -> Index Seek / Index Scan on idx_orders_customer
--   Index Seek (idx_orders_customer)  est rows: 12   actual rows: 12
-- Non-selective predicate (most rows) -> full table read
SELECT o.order_id FROM orders AS o WHERE o.status <> ''cancelled'';
--   Seq Scan / Clustered Index Scan on orders  actual rows: 9,800,000
